#include <assert.h>
#include <string.h>
#include <stdio.h>
typedef struct {int calls;dl_grant_revoke_result outcome;dl_grant_broker *broker;} fixture;
static dl_grant_revoke_result revoke(void *user,const char *resource){fixture *f=user;f->calls++;assert(!strcmp(resource,"opaque-owned-reference"));assert(!dl_grant_valid(f->broker,"lease","chat","hash",110));return f->outcome;}
int main(void){sqlite3 *db=NULL;assert(sqlite3_open(":memory:",&db)==SQLITE_OK);dl_grant_broker *a=dl_grant_open(db,"alice",1),*b=dl_grant_open(db,"bob",1);assert(a&&b);fixture f={0,DL_GRANT_NEEDS_USER,a};dl_grant_adapter adapter={"fixture-protocol",&f,revoke};assert(dl_grant_register(a,&adapter));assert(!dl_grant_register(a,&adapter));assert(!dl_grant_issue(a,"unsupported","chat","unknown","opaque-owned-reference","hash",100,200));assert(dl_grant_issue(a,"lease","chat","fixture-protocol","opaque-owned-reference","hash",100,200));assert(!dl_grant_issue(a,"lease","chat","fixture-protocol","opaque-owned-reference","hash",100,200));assert(dl_grant_valid(a,"lease","chat","hash",110));assert(!dl_grant_valid(a,"lease","chat","different-arguments",110));assert(!dl_grant_valid(a,"lease","other-chat","hash",110));assert(!dl_grant_valid(a,"lease","chat","hash",99));assert(!dl_grant_valid(a,"lease","chat","hash",200));assert(!dl_grant_valid(a,"lease","chat","hash",110));assert(!dl_grant_valid(b,"lease","chat","hash",110));assert(!dl_grant_revoke(b,"lease",110));assert(!f.calls);assert(dl_grant_revoke(a,"lease",110));char *rows=dl_grant_list(a,"");assert(rows&&strstr(rows,"needs_user")&&!strstr(rows,"opaque-owned-reference"));dl_grant_free(rows);assert(!dl_grant_valid(a,"lease","chat","hash",111));f.outcome=DL_GRANT_RETRY;assert(dl_grant_revoke(a,"lease",112));f.outcome=DL_GRANT_REVOKED;assert(dl_grant_revoke(a,"lease",113));assert(f.calls==3);assert(dl_grant_revoke(a,"lease",114)&&f.calls==3);rows=dl_grant_list(a,"");assert(strstr(rows,"\"revoked\":113"));dl_grant_free(rows);
 assert(dl_grant_issue(a,"restart-lease","chat","fixture-protocol","opaque-owned-reference","hash",100,500));
 assert(sqlite3_exec(db,"UPDATE capability_leases SET state='revoking' WHERE id='lease'",NULL,NULL,NULL)==SQLITE_OK);dl_grant_close(a);a=dl_grant_open(db,"alice",1);rows=dl_grant_list(a,"");assert(strstr(rows,"unknown"));dl_grant_free(rows);assert(f.calls==3);assert(!dl_grant_valid(a,"lease","chat","hash",115));assert(!dl_grant_valid(a,"restart-lease","chat","hash",115));dl_grant_close(a);dl_grant_close(b);sqlite3_close(db);puts("PASS independent C grant ownership, argument binding, expiry, immediate local denial, interactive/failed/retried revocation, idempotence and no replay after interruption; fixture adapter only");return 0;}
